from pathlib import Path
import runpy
root=Path(__file__).resolve().parents[2]
c=runpy.run_path(str(Path(__file__).with_name('build-content.py')))
css=(Path(__file__).with_name('sire-composer.css')).read_text()
css+='''
+:root{--bg:#fbfaf8;--bg2:#fff;--text:#1a1a1a;--heading:#0b0b0b;--nav:#555;--dim:#676560;--chip-bg:#f2f1ed;--chip-border:#e2e0da;--sire:#a83451;--grad-solid:linear-gradient(90deg,#a83451,#de875d);--ease:cubic-bezier(.16,1,.3,1)}
+body{background:var(--bg)}.chat-page{max-width:800px;margin:auto;padding:50px 24px 90px}.chat-hero{text-align:center}.chat-hero h1{font-size:clamp(32px,4vw,48px);letter-spacing:-.035em;margin-bottom:20px}.chat-hero p{max-width:580px;margin:0 auto}.chat-hero .eyebrow{margin-bottom:18px}.chat-hero em{font-style:normal;color:var(--sire)}.composer-shell{margin-top:34px}.composer{border-radius:18px}.thread{min-height:220px;max-height:min(52vh,460px);scrollbar-gutter:stable}.msg .bubble{white-space:pre-wrap;overflow-wrap:anywhere;max-width:88%;font-size:14px}.msg.ai .bubble a{text-decoration:underline}.askbar input{min-width:0;font-size:16px;line-height:1.5}.send,.voice-btn{flex-shrink:0;width:44px;height:44px}.askbar input:focus-visible{outline:2px solid var(--sire);outline-offset:4px;border-radius:3px}.chat-hint{text-align:center;font-size:12px;color:var(--dim);margin-top:20px}.chips{margin-top:28px}.chip{min-height:44px;font:inherit;font-size:12px}.chat-status{min-height:20px;text-align:center;font-size:12px;color:var(--dim);margin-top:18px}.retry{color:var(--sire);background:none;border:0;text-decoration:underline;padding:8px;font-size:13px}.bubble pre{white-space:pre-wrap;padding:12px;font-size:12px;margin:12px 0}.bubble code{font-size:.9em}.chat-more{margin:55px auto 0;max-width:640px;border-top:1px solid var(--line);padding-top:28px;display:flex;justify-content:space-between;gap:24px;font-size:13px}.send:disabled,.voice-btn:disabled{opacity:.5;cursor:wait}.voice-btn[hidden]{display:none}.mode-note{display:block;font-size:11px;color:var(--dim);margin-top:10px}.chat-hint a{color:var(--sire)}
+@media(prefers-color-scheme:dark){:root{--bg:#201f21;--bg2:#29272a;--text:#e9e4e1;--heading:#f1edeb;--nav:#bbb4b5;--dim:#b5adb0;--chip-bg:#302b2e;--chip-border:#494146;--sire:#ed9cb1;--grad-solid:linear-gradient(90deg,#a83451,#de875d)}}
+@media(max-width:767px){.chat-page{padding-top:36px}.thread{min-height:200px;max-height:46vh}.composer{padding:16px 12px}.chat-more{flex-direction:column;gap:12px}.msg .bubble{max-width:95%}.chips{gap:8px}.chat-hero h1{font-size:34px}}
'''.replace('\n+','\n')
(root/'site/assets/chat.css').write_text(css)
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#ececeb"><title>Ask about Serenity — setup help, with sources</title><meta name="description" content="Ask questions about Serenity, get cited setup guidance, and find the right documentation."><link rel="canonical" href="https://serenity.sire.run/chat/"><link rel="icon" href="/assets/brand.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/chat.css"><script src="/assets/chat-config.js" defer></script><script src="/assets/chat.js" defer></script></head><body>{c['nav']}<main class="chat-page" id="main"><header class="chat-hero"><p class="eyebrow">A little help getting started</p><h1>Your questions.<br><em>With sources.</em></h1><p>Ask about setup, sources, or how Serenity fits your work. Answers draw on the documentation, with links so you can check.</p></header><div class="composer-shell"><form class="composer" id="askForm"><div class="thread" id="thread" role="log" aria-live="polite" aria-label="Conversation"><div class="msg ai"><div class="bubble">What would you like Serenity to remember?<br>Start with a setup question, or pick one below.</div></div></div><div class="askbar"><input id="q" name="question" type="text" placeholder="Ask about Serenity…" aria-label="Your question about Serenity" maxlength="1000" required autocomplete="off"><button class="voice-btn" id="voiceBtn" type="button" aria-pressed="false" aria-label="Use voice input" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15a3.5 3.5 0 0 0 3.5-3.5V6a3.5 3.5 0 1 0-7 0v5.5A3.5 3.5 0 0 0 12 15zm5.5-3.5a5.5 5.5 0 0 1-11 0H5a7 7 0 0 0 6 6.93V21h2v-2.57A7 7 0 0 0 19 11.5z"/></svg></button><button class="send" type="submit" aria-label="Send question"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></div></form><p class="chat-hint">Public product questions only. Don’t share private notes or secrets. <a href="/docs/privacy/#chat">How chat works with your data</a></p><div class="chips" aria-label="Suggested questions"><button class="chip" data-question="How do I install Serenity and search my first notes folder?">Help me get started ↗</button><button class="chip" data-question="Can I use Serenity without a model or API key?">Can I use it without AI?</button><button class="chip" data-question="Does my data stay on my machine?">Where does my data go?</button></div><p id="chat-status" class="chat-status" role="status"></p><noscript><p>Chat needs JavaScript. All <a href="/docs/">documentation</a> and <a href="/get-started/">installation steps</a> are available without it.</p></noscript></div><div class="chat-more"><a href="/get-started/">Ready to try it? Install Serenity →</a><a href="https://ndungu.dev">Need custom AI automation? Work with David ↗</a></div></main>{c['footer']}</body></html>'''
